import{_ as a,o as t,c as n,a3 as i}from"./chunks/framework.B5WAEDB7.js";const m=JSON.parse('{"title":"Calendar","description":"Display entries on a calendar sheet, with a start date and an optional end date.","frontmatter":{"title":"Calendar","description":"Display entries on a calendar sheet, with a start date and an optional end date."},"headers":[],"relativePath":"en/ansichten/kalender.md","filePath":"en/ansichten/kalender.md","lastUpdated":1787319236000}'),o={name:"en/ansichten/kalender.md"};function r(d,e,s,l,c,p){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="calendar" tabindex="-1">Calendar <a class="header-anchor" href="#calendar" aria-label="Permalink to &quot;Calendar&quot;">​</a></h1><p>The <strong>Calendar</strong> view shows entries on a calendar sheet, positioned via a date field.</p><p>The interface describes it as <em>Manage appointments at a glance</em>.</p><p><strong>Suited for:</strong> appointments, deadlines, bookings, vacation planning, editorial schedules.</p><h2 id="requirement-a-date-field" tabindex="-1">Requirement: a date field <a class="header-anchor" href="#requirement-a-date-field" aria-label="Permalink to &quot;Requirement: a date field&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">No calendar without a date field</p><blockquote><p><em>To see a Calendar, your Grid needs at least one date field.</em></p></blockquote><p>If one is missing, ApptiveGrid offers to create one directly (<em>Create a date field</em>).</p></div><p>The column types <strong>Date</strong> and <strong>Date and time</strong> both work.</p><h2 id="create-a-calendar" tabindex="-1">Create a calendar <a class="header-anchor" href="#create-a-calendar" aria-label="Permalink to &quot;Create a calendar&quot;">​</a></h2><ol><li>Under the Grid, choose <strong>Create view</strong>.</li><li>Choose <strong>Calendar</strong>.</li><li>Under <strong>Calendar settings</strong>, set the date field.</li></ol><p>The dialog is called <em>Set a date field for events</em>:</p><blockquote><p><em>Which date field would you like to use for this view? Your entries are placed based on the data in this field.</em></p></blockquote><h2 id="a-period-instead-of-a-single-date" tabindex="-1">A period instead of a single date <a class="header-anchor" href="#a-period-instead-of-a-single-date" aria-label="Permalink to &quot;A period instead of a single date&quot;">​</a></h2><p>The dialog has two fields:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>From</strong></td><td>Start date — determines the position</td></tr><tr><td><strong>To (optional)</strong></td><td>End date — turns the appointment into a period</td></tr></tbody></table><p>Without <em>To</em>, the entry appears as a single appointment. With <em>To</em>, it spans multiple days.</p><div class="tip custom-block"><p class="custom-block-title">Create two fields for periods</p><p>For vacations, project phases, or bookings, you need <strong>two</strong> date columns in the Grid — for example <code>Start</code> and <code>End</code>. Create both before configuring the calendar view, or <em>To</em> won&#39;t be available to choose.</p></div><h2 id="switching-the-display" tabindex="-1">Switching the display <a class="header-anchor" href="#switching-the-display" aria-label="Permalink to &quot;Switching the display&quot;">​</a></h2><p>Three time grids:</p><ul><li><strong>Day</strong></li><li><strong>Week</strong></li><li><strong>Month</strong></li></ul><p>Use <strong>Today</strong> to jump back to the current date.</p><div class="tip custom-block"><p class="custom-block-title">Which grid for what</p><p><em>Month</em> for a full overview and capacity planning. <em>Week</em> for day-to-day work. <em>Day</em> for appointments with a time — that&#39;s where the <em>Date and time</em> column type pays off, since entries appear sorted by time of day.</p></div><h2 id="creating-an-appointment" tabindex="-1">Creating an appointment <a class="header-anchor" href="#creating-an-appointment" aria-label="Permalink to &quot;Creating an appointment&quot;">​</a></h2><p>Use <strong>New event</strong> to create an entry directly from the calendar. The chosen date is carried over.</p><p>The entry is created in the underlying Grid — with all fields, including ones not visible in the calendar.</p><h2 id="filters-and-multiple-calendars" tabindex="-1">Filters and multiple calendars <a class="header-anchor" href="#filters-and-multiple-calendars" aria-label="Permalink to &quot;Filters and multiple calendars&quot;">​</a></h2><p>Filters work as in any view.</p><div class="tip custom-block"><p class="custom-block-title">Multiple calendars on the same data</p><p>Instead of maintaining one overloaded calendar, create multiple views: &quot;My appointments&quot; with <code>Assignee</code> <code>is</code> <code>logged-in user</code>, &quot;Confirmed only&quot; with a status filter, &quot;Deadlines&quot; on a different date field.</p><p>Each view can use a <strong>different</strong> date field — the same Grid can thus be viewed by start date <em>and</em> by due date.</p></div><p>→ <a href="/en/ansichten/filtern-sortieren-gruppieren">Filtering, Sorting, Grouping</a></p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/ansichten/was-ist-eine-ansicht">What is a View</a></li><li><a href="/en/ansichten/timeline">Timeline</a> — for periods spanning long stretches</li><li><a href="/en/referenz/spaltentypen">Column type reference</a></li></ul>',30)])])}const u=a(o,[["render",r]]);export{m as __pageData,u as default};
